$ErrorActionPreference='Stop';Add-Type -AssemblyName PresentationFramework
function Fail([string]$m){[Windows.MessageBox]::Show($m,'Merch Forge · Amazon print profile',[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Error)|Out-Null;exit 1}
function Sha([string]$p){return (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
$dlg=New-Object Microsoft.Win32.OpenFileDialog;$dlg.Title='Select filled Amazon print profile JSON';$dlg.Filter='JSON profile (*.json)|*.json';if($dlg.ShowDialog()-ne$true){exit 0};$source=$dlg.FileName
try{$p=Get-Content -LiteralPath $source -Raw -Encoding UTF8|ConvertFrom-Json}catch{Fail ('Invalid JSON: '+$_.Exception.Message)};if([string]$p.schema-ne'forge.amazon_print_profile_attestation.v1'){Fail 'Unsupported print profile schema.'};if([bool]$p.attested-ne$true){Fail 'Set attested=true only after copying exact values from the current Amazon Merch product template.'}
$w=[int]$p.canvas_width_px;$h=[int]$p.canvas_height_px;$dpi=[int]$p.dpi;if($w-lt500-or$w-gt10000-or$h-lt500-or$h-gt10000){Fail 'Canvas dimensions must be between 500 and 10,000 pixels.'};if($dpi-lt72-or$dpi-gt600){Fail 'DPI is outside the accepted profile range.'};if(([string]$p.file_format).ToLowerInvariant()-ne'png' -or ([string]$p.background).ToLowerInvariant()-ne'transparent'){Fail 'This Forge apparel profile requires transparent PNG.'};if([string]$p.template_file_sha256-notmatch'^[0-9a-fA-F]{64}$'){Fail 'template_file_sha256 must be the SHA-256 of the exact current Amazon template file.'};if([string]::IsNullOrWhiteSpace([string]$p.marketplace)-or[string]::IsNullOrWhiteSpace([string]$p.product_type_key)-or[string]::IsNullOrWhiteSpace([string]$p.template_key)){Fail 'marketplace, product_type_key and template_key are required.'}
$refs=@($p.source_refs);if($refs.Count-lt1){Fail 'At least one Amazon source_ref is required.'};foreach($r in $refs){try{$u=[Uri][string]$r;$refHost=$u.Host.ToLowerInvariant();if($u.Scheme-ne'https'-or $refHost-notin@('developer.amazon.com','merch.amazon.com','sellercentral.amazon.com')){Fail ('Non-Amazon or non-HTTPS source_ref is not allowed: '+[string]$r)}}catch{Fail ('Invalid source_ref: '+[string]$r)}}
try{$capt=[DateTime]::Parse([string]$p.captured_at).ToUniversalTime();$valid=[DateTime]::Parse([string]$p.valid_until).ToUniversalTime()}catch{Fail 'captured_at and valid_until must be valid ISO date/time values.'};if($capt-gt[DateTime]::UtcNow.AddMinutes(10)){Fail 'captured_at is in the future.'};if($valid-le[DateTime]::UtcNow){Fail 'valid_until is already expired.'};if($valid-le$capt){Fail 'valid_until must be later than captured_at.'};if(($valid-$capt).TotalDays-gt120){Fail 'valid_until may be at most 120 days after captured_at; re-attest current channel templates periodically.'}
$normalized=[ordered]@{schema='forge.amazon_print_profile.v1';authority_kind='owner_attested_external';attested=$true;marketplace=[string]$p.marketplace;product_type_key=[string]$p.product_type_key;template_key=[string]$p.template_key;canvas_width_px=$w;canvas_height_px=$h;dpi=$dpi;file_format='png';background='transparent';captured_at=$capt.ToString('o');valid_until=$valid.ToString('o');template_file_sha256=([string]$p.template_file_sha256).ToLowerInvariant();source_refs=@($refs);source_file_sha256=(Sha $source);source_file_name=[IO.Path]::GetFileName($source);imported_at=[DateTime]::UtcNow.ToString('o');independent_verification=$false;note='Owner-attested values from a current Amazon Merch product template; not independently verified by Merch Forge.'}
$root=Join-Path $env:LOCALAPPDATA 'MerchForge\channel-profiles';if(-not(Test-Path $root)){New-Item -ItemType Directory -Path $root -Force|Out-Null};$dest=Join-Path $root 'amazon-merch.json';$tmp=$dest+'.tmp.'+[Guid]::NewGuid().ToString('N');$utf8=New-Object Text.UTF8Encoding -ArgumentList $false;[IO.File]::WriteAllText($tmp,($normalized|ConvertTo-Json -Depth 20),$utf8);Move-Item -LiteralPath $tmp -Destination $dest -Force;[Windows.MessageBox]::Show(('Amazon print profile imported.\n\nCanvas: {0} x {1}\nDPI: {2}\nValid until: {3}\n\nRestart/Refresh Forge to re-run local print checks.' -f $w,$h,$dpi,$valid.ToString('u')),'Merch Forge · Amazon print profile',[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Information)|Out-Null
